"""Version Slack requests without treating unfurls as new user instructions."""

import asyncio
import hashlib
import json
import logging
import sqlite3
from dataclasses import dataclass, field
from decimal import Decimal, InvalidOperation

from hermes_constants import get_hermes_home

logger = logging.getLogger(__name__)


def fingerprint(text):
    return hashlib.sha256(str(text or "").encode()).hexdigest()


def version(raw):
    edited = raw.get("edited") or {}
    try:
        value = Decimal(str(edited.get("ts") or raw.get("ts") or "0"))
        return value if value.is_finite() else Decimal(0)
    except (InvalidOperation, ValueError):
        return Decimal(0)


@dataclass
class Reply:
    ids: list = field(default_factory=list)
    obligations: dict = field(default_factory=dict)
    lock: asyncio.Lock = field(default_factory=asyncio.Lock)


@dataclass
class Revision:
    key: tuple
    version: Decimal
    digest: str
    reply: Reply = field(default_factory=Reply)
    event: object = None


class MessageEdits:
    def __init__(self):
        self.path = get_hermes_home() / "slack-message-edits.sqlite"
        self.records = {}
        self.processing = {}
        self.locks = {}

    def key(self, adapter, raw, payload=None):
        return (adapter._event_team_id(raw, payload), str(raw.get("channel") or ""),
                str(raw.get("user") or ""), str(raw.get("ts") or ""))

    def lookup(self, key):
        if key in self.records:
            return self.records[key]
        if self.path.exists():
            with sqlite3.connect(self.path) as db:
                row = db.execute("SELECT version,digest,replies FROM message_versions WHERE identity=?",
                                 (json.dumps(key),)).fetchone()
            if row:
                saved = json.loads(row[2])
                reply = Reply(saved) if isinstance(saved, list) else Reply(saved['ids'], saved['obligations'])
                self.records[key] = Revision(key, Decimal(row[0]), row[1], reply)
                return self.records[key]

    def user_edit(self, adapter, envelope, payload=None):
        raw = dict(envelope.get("message") or {})
        for name in ("channel", "team", "team_id"):
            raw.setdefault(name, envelope.get(name))
        edited = raw.get("edited")
        if (not isinstance(edited, dict) or not raw.get("user")
                or edited.get("user") != raw.get("user") or not edited.get("ts")):
            return False
        known = self.lookup(self.key(adapter, raw, payload))
        if known:
            incoming = version(raw)
            if incoming <= known.version:
                return False
            if fingerprint(raw.get("text")) == known.digest:
                old_version = str(known.version)
                known.version = incoming
                for obligation, stored_version in known.reply.obligations.items():
                    if stored_version == old_version:
                        known.reply.obligations[obligation] = str(incoming)
                if self.path.exists():
                    with sqlite3.connect(self.path) as db:
                        db.execute("UPDATE message_versions SET version=?,replies=? WHERE identity=?",
                                   (str(incoming), json.dumps({'ids':known.reply.ids,
                                    'obligations':known.reply.obligations}), json.dumps(known.key)))
                return False
            return True
        previous = envelope.get("previous_message")
        if isinstance(previous, dict):
            return (previous.get("user") == raw.get("user") and previous.get("ts") == raw.get("ts")
                    and fingerprint(previous.get("text")) != fingerprint(raw.get("text")))
        return True  # e.g. a mention added to an ignored message

    def claim(self, adapter, raw, payload=None):
        key = self.key(adapter, raw, payload)
        previous = self.lookup(key)
        incoming = version(raw)
        if previous and incoming <= previous.version:
            return None
        record = Revision(key, incoming, fingerprint(raw.get("text")),
                          previous.reply if previous else Reply())
        self.records[key] = record
        # Disk retains completed mappings; bound the process-local intake cache.
        if len(self.records) > 4000:
            oldest = next(iter(self.records))
            if oldest != key:
                self.records.pop(oldest)
        return record

    def current(self, record):
        return self.records.get(record.key) is record

    def for_reply(self, event):
        inbound = str(event.ledger_message_id or event.message_id or "")
        bound = getattr(event, "_slack_revision", None)
        if bound and (inbound == bound.key[3] or inbound.startswith(bound.key[3] + ":edit:")):
            return bound
        if not inbound:
            return None
        source = event.source
        record = self.lookup((source.scope_id or "", source.chat_id, source.user_id or "", inbound))
        if record:
            return record
        # Native queued finals carry the terminal inbound ID on the opening event. Slack message
        # IDs are unique within a channel; a validated queued sender can differ from the opener.
        matches = [r for r in self.records.values()
                   if r.key[:2] == (source.scope_id or "", source.chat_id) and r.key[3] == inbound]
        return matches[0] if len(matches) == 1 else None

    def edited(self, record):
        return record.version > version({"ts": record.key[3]})

    def for_obligation(self, obligation, chat_id):
        records = list(self.records.values())
        if self.path.exists():
            with sqlite3.connect(self.path) as db:
                keys = [json.loads(row[0]) for row in db.execute('SELECT identity FROM message_versions')]
            records.extend(self.lookup(tuple(key)) for key in keys if key[1] == chat_id)
        for record in records:
            if record and record.key[1] == chat_id and obligation in record.reply.obligations:
                obsolete = record.reply.obligations[obligation] != str(record.version)
                return record, obsolete
        return None, False

    def envelope_raw(self, envelope):
        raw = dict(envelope.get("message") or {}) if envelope.get("subtype") == "message_changed" else dict(envelope)
        for name in ("channel", "team", "team_id"):
            if not raw.get(name):
                raw[name] = envelope.get(name)
        return raw

    def release_failed(self, key, raw, previous):
        current = self.records.get(key)
        if current is not previous and current and current.version == version(raw):
            if previous is None:
                self.records.pop(key, None)
            else:
                self.records[key] = previous

    @staticmethod
    def same_message(left, right):
        if left is None or right is None:
            return False
        return (str(left.message_id or "") == str(right.message_id or "")
                and all(getattr(left.source, name, None) == getattr(right.source, name, None)
                        for name in ("scope_id", "chat_id", "user_id")))

    async def dispatch(self, adapter, event, record, *, edited):
        if not self.current(record) or adapter._drop_unresolved(event):
            return
        runner = adapter.gateway_runner
        if runner and not runner._is_user_authorized_for_source(event.source):
            return
        key = adapter._event_session_key(event)
        lock = self.locks.setdefault(key, asyncio.Lock())
        async with lock:
            if not self.current(record):
                return
            record.event = event
            event._slack_revision = record
            if not edited:
                await adapter.handle_message(event)
                return
            edit_context = ('This Slack message was edited. The following request replaces its '
                            'previous wording. Work only on the updated request.')
            event.channel_context = '\n\n'.join(part for part in (event.channel_context, edit_context) if part)
            from gateway.delivery_ledger import supersede_obligation
            for obligation in tuple(record.reply.obligations):
                await asyncio.to_thread(supersede_obligation, obligation)
            # A pending edit updates its place in the queue; another active request keeps running.
            state = runner._peek_session_state(key) if runner else None
            pending = adapter._pending_messages.get(key)
            if self.same_message(pending, event):
                adapter._pending_messages[key] = event
                event._gateway_accepted = True
                return
            overflow = state.conversation.queued_events if state else []
            for index, queued in enumerate(overflow):
                if self.same_message(queued, event):
                    overflow[index] = event
                    event._gateway_accepted = True
                    return
            active = self.processing.get(key)
            if state and state.turn.ctx:
                ctx = state.turn.ctx
                active = type(event)(text="", source=ctx.source, message_id=ctx.inbound_message_id)
            elif state and state.turn.event:
                active = state.turn.event
            if self.same_message(active, event):
                generation = None
                if runner:
                    generation = runner._interrupt_running_turn(
                        key, interrupt_reason="Slack message edited", invalidation_reason="message_edited")
                guard = adapter._active_sessions.get(key)
                if guard:
                    guard.set()
                task = adapter._session_tasks.get(key)
                # Own the lane while the old finally unwinds. Its queued follow-ups stay parked.
                adapter._session_tasks[key] = asyncio.current_task()
                if task is not None and not task.done():
                    adapter._expected_cancelled_tasks.add(task)
                    task.cancel()
                    try:
                        await asyncio.wait_for(asyncio.shield(task), 5)
                    except asyncio.CancelledError:
                        if asyncio.current_task().cancelling():
                            raise
                    except asyncio.TimeoutError:
                        logger.warning("Edited Slack turn is still unwinding: %s", key)
                if runner:
                    runner._drop_turn_slot(key, run_generation=generation)
                adapter._release_session_guard(key)
                if adapter._session_tasks.get(key) is asyncio.current_task():
                    adapter._session_tasks.pop(key, None)
            policy = getattr(adapter, "_workspace_membership", None)
            service = getattr(policy, "vault_service", None)
            if service:
                await service.channel_control.stop_message(event.source, event.message_id)
            if self.current(record):
                await adapter.handle_message(event)

    async def save(self, record):
        # A send that was already accepted by Slack may complete after an edit arrived.
        # The shared reply IDs still belong to the latest version of that same request.
        latest = self.records.get(record.key, record)
        values = (json.dumps(record.key), str(latest.version), latest.digest, json.dumps({
            'ids':record.reply.ids, 'obligations':record.reply.obligations}))
        def write():
            self.path.parent.mkdir(parents=True, exist_ok=True)
            with sqlite3.connect(self.path) as db:
                db.execute("CREATE TABLE IF NOT EXISTS message_versions "
                           "(identity TEXT PRIMARY KEY,version TEXT,digest TEXT,replies TEXT)")
                db.execute("INSERT INTO message_versions VALUES (?,?,?,?) ON CONFLICT(identity) "
                           "DO UPDATE SET version=excluded.version,digest=excluded.digest,replies=excluded.replies "
                           "WHERE CAST(excluded.version AS REAL)>=CAST(message_versions.version AS REAL)", values)
        await asyncio.to_thread(write)

    async def update_reply(self, adapter, record, content, metadata):
        from gateway.platforms.base import SendResult
        async with record.reply.lock:
            if not self.current(record):
                return SendResult(success=True)
            chunks = adapter.truncate_message(adapter.format_message(content), adapter.MAX_MESSAGE_LENGTH)
            client = adapter._client_for(record.key[1], metadata)
            for index, chunk in enumerate(chunks):
                if not self.current(record):
                    return SendResult(success=True)
                args = {"channel": record.key[1], "text": chunk, "blocks": []}
                if index < len(record.reply.ids):
                    args["ts"] = record.reply.ids[index]
                    await client.chat_update(**args)
                else:
                    args.pop("blocks")
                    args["thread_ts"] = adapter._resolve_thread_ts(record.key[3], metadata)
                    response = await client.chat_postMessage(**args)
                    record.reply.ids.append(response["ts"])
            while len(record.reply.ids) > len(chunks):
                await client.chat_delete(channel=record.key[1], ts=record.reply.ids[-1])
            logger.debug(
                "[Slack] Ignoring thread reply without mention "
                "(thread_require_mention=true): channel=%s thread_ts=%s", channel_id,
                event_thread_ts)
            return False
        if free_channel:
            return True
        if not is_mentioned:
            return await self._should_wake_on_unmentioned_message(
                event_thread_ts=event_thread_ts, channel_id=channel_id, user_id=user_id,
                team_id=team_id, is_thread_reply=is_thread_reply,
                chat_type="dm" if is_dm else "group")
        return True

    def _normalize_changed_message(self, event: dict, payload=None) -> Optional[dict]:
        """Turn a ``message_changed`` envelope into a plain message event.
        None if malformed, unchanged, or an unfurl of an already routed message. The edit's own ts rides
        along as ``_slack_changed_event_ts`` for dedup."""
        updated_message = event.get("message")
        if not isinstance(updated_message, dict):
            return None
        original_message_ts = str(updated_message.get("ts") or "")
        user_edit = self._message_edits.user_edit(self, event, payload)
        if (not user_edit and original_message_ts
                and original_message_ts in self._processed_message_ts):
            return None
        edited = updated_message.get("edited")
        edited_ts = str(edited.get("ts") or "") if isinstance(edited, dict) else ""
        outer_event_ts = str(event.get("ts") or "")
        changed_event_ts = (
            str(event.get("event_ts") or edited_ts or "")
            or (outer_event_ts if outer_event_ts != original_message_ts else "")
            or (f"{original_message_ts}:changed" if original_message_ts else ""))
        normalized_event = dict(updated_message)
        if user_edit:
            normalized_event["_slack_user_edit"] = True
        for key in ("channel", "channel_type", "team", "team_id"):
            if not normalized_event.get(key) and event.get(key):
                normalized_event[key] = event.get(key)
        if changed_event_ts:
            normalized_event["_slack_changed_event_ts"] = changed_event_ts
        return normalized_event

    @staticmethod
    def _append_link_unfurls(text: str, slack_attachments: list) -> str:
        """Append link-unfurl previews (``attachments``) to ``text``; ``is_msg_unfurl`` echoes our
        own content and is skipped. Dedup matches the rendered section, not the bare URL (which is
        usually already in the user's text while the preview body is not)."""
        att_parts: list[str] = []
        blocks_budget = _SLACK_UNFURL_BLOCKS_MAX_CHARS
        for att in slack_attachments:
        # the runner's own auth check only runs after MessageEvent is built.
        policy = getattr(self, "_workspace_membership", None)
        if policy is not None:
            try:
                if not await policy.prepare_message(user_id, channel_id, team_id):
                    return
            except Exception:
                logger.exception("[Slack onboarding] message membership check failed")
                return
        elif self._early_reject_unauthorized(user_id, channel_id, is_dm):
            return
        thread_ts = self._session_thread_ts(event, ts, is_dm, assistant_meta)
        bot_uid = self._team_bot_user_ids.get(team_id, self._bot_user_id)
        # Mentions may live only in Block Kit blocks.
        # See #52387.
        routing_text = _slack_mention_detection_text(event) or original_text or ""
        is_mentioned = bool(
            (bot_uid and f"<@{bot_uid}>" in routing_text)
            or self._slack_message_matches_mention_patterns(routing_text))
        event_thread_ts = event.get("thread_ts")
        is_thread_reply = bool(event_thread_ts and event_thread_ts != ts)
        # Internal triggers (reactions) skip the mention requirement but NOT
        # allowed_channels or user authorization.
        force_process = bool(event.get("_hermes_force_process")) or bool(
            event.get("_slack_user_edit")
            and self._message_edits.lookup(self._message_edits.key(self, event, payload)))
        if await self._peer_bot_drop(event, user_id, bot_uid, channel_id, team_id, is_mentioned):
            return
        if (
            not is_one_to_one_dm and bot_uid and not await self._channel_gate_allows(
            channel_id=channel_id, routing_text=routing_text, bot_uid=bot_uid,
            is_mentioned=is_mentioned, is_thread_reply=is_thread_reply,
            event_thread_ts=event_thread_ts, user_id=user_id, team_id=team_id, is_dm=is_dm,
            force_process=force_process)):
            return
        # Claim the message ts HERE: a link unfurl emits `message_changed` with a different event
        # ts, so only the `_processed_message_ts` guard stops a duplicate turn, and it must be set
        # before the slow enrichment awaits. Claiming before the filters would let an ignored
        # original block a later "@bot" edit from summoning the bot.
        _claim_ts = str(event.get("ts") or "")
        # A changed event can pass normalization while the original is awaiting
        # admission/channel checks. Recheck after those awaits, then claim with
        # no intervening await so an unfurl cannot become a second user turn.
        if (event.get("_slack_changed_event_ts") and not event.get("_slack_user_edit")
                and _claim_ts in self._processed_message_ts):
            return
        revision = self._message_edits.claim(self, event, payload)
        if revision is None:
            return
        if _claim_ts:
            self._remember_processed_message_ts(_claim_ts)
        if is_mentioned:
            text, original_text, command_probe_text, is_command_text = self._apply_bot_mention(
                text, original_text, command_probe_text, is_command_text, bot_uid, thread_ts,
                team_id)
        # Thread history stays out of ``text``: prepending would push a command off char zero.
        (
            channel_context, thread_root_media_urls, thread_root_media_types,
        ) = await self._hydrate_thread_context(
            channel_id=channel_id, event_thread_ts=event_thread_ts, ts=ts, user_id=user_id,
            team_id=team_id, is_thread_reply=is_thread_reply, is_mentioned=is_mentioned,
            is_dm=is_dm)
        # Thread-root media is delivered ahead of the trigger message's own files.
        media_urls, media_types, media_text_inlined, text = await self._collect_inbound_media(
            event, channel_id, team_id, text, thread_root_media_urls, thread_root_media_types)
        msg_event = await self._build_message_event(
            event, text=text, original_text=original_text, command_probe_text=command_probe_text,
            is_command_text=is_command_text, channel_id=channel_id, team_id=team_id, ts=ts,
            user_id=user_id, thread_ts=thread_ts, is_dm=is_dm, media_urls=media_urls,
            media_types=media_types, media_text_inlined=media_text_inlined, channel_context=channel_context)
        if not self._message_edits.current(revision):
            return
        msg_event._slack_revision = revision
        if policy is not None and not await policy.prepare_event(msg_event):
            return
        # React only when directly addressed; MPIMs are shared, so they need a
        # mention like any channel.
        ack_enabled = self._acknowledgement_reactions_enabled()
        ack_eligible = (not is_command_text and not force_process
                        and not self._event_declares_bot_sender(event))
        if (self._reactions_enabled() and
                (ack_eligible if ack_enabled else (is_one_to_one_dm or is_mentioned))):
            self._track_reacting_message(team_id, ts)
        # App-context is per-turn UI state: in the user message, not SessionSource (would rebuild
        # the agent per view switch and leak stale context). Inert label, never a channel body.
        context_channel_id = agent_context.get("context_channel_id", "")
        if context_channel_id and context_channel_id != channel_id and not is_command_text:
            msg_event.text = (
                f"[Slack app context: user is viewing channel {context_channel_id}]\n\n"
                f"{msg_event.text}")
        if ts:
            self._remember_processed_message_ts(ts)
        await self._message_edits.dispatch(
            self, msg_event, revision, edited=bool(event.get("_slack_user_edit")))

    async def _build_message_event(
        self, event: dict, *, text: str, original_text: str, command_probe_text: str,
        is_command_text: bool, channel_id: str, team_id: str, ts: str, user_id: str,
        thread_ts: Optional[str], is_dm: bool, media_urls: List[str], media_types: List[str],
        media_text_inlined: List[bool], channel_context: Optional[str]) -> MessageEvent:
        """Resolve names, title the DM thread, and build the ``MessageEvent``. Commands are restored
        from canonical input: the parser needs the token at char zero and enrichment (blocks,
        unfurls, file text, history) must never mutate arguments."""
        if is_command_text:
            text = command_probe_text
        msg_type = MessageType.COMMAND if is_command_text else self._media_message_type(media_types)

